const normalizeLanguage = (language) => {
  const value = String(language || "").toLowerCase();
  return ["en", "ta", "ur", "ar", "ml", "kn", "te"].includes(value) ? value : "en";
};

export const getCurrentUiLanguage = () => {
  if (typeof window === "undefined") return "en";
  return normalizeLanguage(window.localStorage?.getItem("preferredLanguage"));
};

export const translateUiPhrase = (value, language = getCurrentUiLanguage(), params = {}) => {
  const text = String(value ?? "");
  const applyParams = (input) => {
    let output = String(input ?? "");
    Object.entries(params || {}).forEach(([key, paramValue]) => {
      output = output.split(`{{${key}}}`).join(String(paramValue ?? ""));
    });
    return output;
  };

  if (!text || normalizeLanguage(language) === "en") return applyParams(text);

  const lang = normalizeLanguage(language);
  const exact = PHRASES[lang]?.[text];
  if (exact) return applyParams(exact);

  const roleAliases = {
    superadmin: "SuperAdmin",
    hquser: "HQUser",
    supervisor: "Supervisor",
    admin: "Admin",
    employee: "Employee",
    student: "Student",
    parent: "Parent",
    guest: "Guest",
    teacher: "Teacher",
    usthadh: "Usthadh",
    warden: "Warden",
    staff: "Staff",
  };
  const roleAlias = roleAliases[text.toLowerCase()];
  if (roleAlias && PHRASES[lang]?.[roleAlias]) return applyParams(PHRASES[lang][roleAlias]);

  const trimmed = text.trim();
  if (trimmed !== text && PHRASES[lang]?.[trimmed]) {
    return applyParams(text.replace(trimmed, PHRASES[lang][trimmed]));
  }

  if (trimmed.endsWith(":")) {
    const base = trimmed.slice(0, -1).trim();
    const translated = PHRASES[lang]?.[base];
    if (translated) return applyParams(`${translated}:`);
  }

  return applyParams(text);
};

export const isUiRtlLanguage = (language = getCurrentUiLanguage()) => ["ur", "ar"].includes(normalizeLanguage(language));

